"""HTTP entry point for PrivaCare."""

from __future__ import annotations

import argparse
import json
import os
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

from .classifier import InvalidRequest, InvalidSchema
from .deidentifier import InvalidPolicy
from .service import Service

CLASSIFY_PATH = "/v1/classify"
DEIDENTIFY_PATH = "/v1/deidentify"
KNOWN_POST_PATHS = (CLASSIFY_PATH, DEIDENTIFY_PATH)


def env_address() -> tuple[str, int]:
    raw = os.environ.get("PRIVACARE_ADDR", "127.0.0.1:8080")
    host, _, port = raw.rpartition(":")
    if not host or not port.isdigit():
        raise SystemExit(f"invalid PRIVACARE_ADDR: {raw!r}")
    return host, int(port)


class Handler(BaseHTTPRequestHandler):
    service = Service()

    def send_json(self, status: int, payload: dict, extra_headers: tuple[tuple[str, str], ...] = ()) -> None:
        body = json.dumps(payload, ensure_ascii=False, sort_keys=True).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        for name, value in extra_headers:
            self.send_header(name, value)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def send_error_json(self, status: int, code: str, message: str, extra_headers: tuple[tuple[str, str], ...] = ()) -> None:
        self.send_json(status, {"error": {"code": code, "message": message}}, extra_headers)

    def not_found(self) -> None:
        self.send_error_json(404, "not_found", f"no route for {self.path}")

    def method_not_allowed(self) -> None:
        self.send_error_json(
            405,
            "method_not_allowed",
            f"method not allowed for {self.path}",
            (("Allow", "POST"),),
        )

    def route_known_path(self) -> None:
        """405 for the known POST endpoints, 404 for anything else."""
        if self.path in KNOWN_POST_PATHS:
            self.method_not_allowed()
            return
        self.not_found()

    def do_GET(self) -> None:
        if self.path == "/healthz":
            self.send_json(200, self.service.health())
            return
        self.route_known_path()

    def do_POST(self) -> None:
        if self.path == CLASSIFY_PATH:
            self.handle_json_endpoint(self.service.classify)
            return
        if self.path == DEIDENTIFY_PATH:
            self.handle_json_endpoint(self.service.deidentify)
            return
        self.not_found()

    def do_PUT(self) -> None:
        self.route_known_path()

    def do_DELETE(self) -> None:
        self.route_known_path()

    def do_PATCH(self) -> None:
        self.route_known_path()

    def handle_json_endpoint(self, handler) -> None:
        """Shared JSON-body handling for the POST endpoints."""
        content_type = (self.headers.get("Content-Type") or "").split(";", 1)[0].strip().lower()
        if content_type != "application/json":
            self.send_error_json(415, "unsupported_media_type", "Content-Type must be application/json")
            return
        try:
            length = int(self.headers.get("Content-Length") or "0")
        except ValueError:
            length = 0
        raw = self.rfile.read(length) if length > 0 else b""
        try:
            payload = json.loads(raw)
        except ValueError:
            self.send_error_json(400, "invalid_json", "request body is not valid JSON")
            return
        try:
            results = handler(payload)
        except InvalidRequest as exc:
            self.send_error_json(422, "invalid_request", str(exc))
            return
        except InvalidSchema as exc:
            self.send_error_json(422, "invalid_schema", str(exc))
            return
        except InvalidPolicy as exc:
            self.send_error_json(422, "invalid_policy", str(exc))
            return
        self.send_json(200, {"results": results})

    def log_message(self, fmt: str, *args: object) -> None:
        """Silence per-request logging so recorded output stays stable."""


def main() -> int:
    parser = argparse.ArgumentParser(prog="privacare.server", description="医疗数据隐私与合规平台")
    host, port = env_address()
    parser.add_argument("--host", default=host)
    parser.add_argument("--port", type=int, default=port)
    args = parser.parse_args()
    httpd = ThreadingHTTPServer((args.host, args.port), Handler)
    print(f"PrivaCare listening on http://{args.host}:{httpd.server_address[1]}", flush=True)
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        httpd.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Core service surface for PrivaCare.

Later work adds the real capabilities described in README.md behind this
module; keep the public surface here backward compatible.
"""

from __future__ import annotations

from typing import Any

from . import __version__
from .classifier import classify_request
from .deidentifier import deidentify_request


class Service:
    """Health reporting, field classification, and de-identification."""

    name = "privacare"
    version = __version__

    def health(self) -> dict[str, str]:
        return {"status": "ok", "service": self.name, "version": self.version}

    def classify(self, payload: Any) -> list[dict]:
        """Classify sensitive fields in a /v1/classify request payload."""
        return classify_request(payload)

    def deidentify(self, payload: Any) -> list[dict]:
        """De-identify records in a /v1/deidentify request payload."""
        return deidentify_request(payload)

"""Policy-driven de-identification for medical records.

Built on the classifier: leaves are found with the exact same rules and the
request-scoped schema, then each record is deep-copied and transformed. The
module is pure and request-scoped — caller data is never mutated and nothing
leaks across requests.
"""

from __future__ import annotations

import copy
from typing import Any

from .classifier import (
    CATEGORIES,
    InvalidRequest,
    _parse_rules,
    _pointer,
    _record_hits,
    _validate_records,
)

ACTIONS: tuple[str, ...] = ("keep", "redact", "drop")

_CATEGORY_SET = frozenset(CATEGORIES)
_ACTION_SET = frozenset(ACTIONS)

# When a leaf hits several categories, the strictest configured action wins.
_ACTION_PRIORITY = {"drop": 0, "redact": 1, "keep": 2}


class InvalidPolicy(ValueError):
    """The caller-supplied de-identification policy is malformed."""


def _parse_policy(raw: Any) -> dict[str, str]:
    if not isinstance(raw, dict) or not raw:
        raise InvalidPolicy("policy must be a non-empty object")
    policy: dict[str, str] = {}
    for category, action in raw.items():
        if category not in _CATEGORY_SET:
            raise InvalidPolicy("policy contains an unknown category")
        if not isinstance(action, str) or action not in _ACTION_SET:
            raise InvalidPolicy("policy actions must be 'keep', 'redact' or 'drop'")
        policy[category] = action
    return policy


def _apply_action(node: Any, segments: tuple[str, ...], action: str) -> None:
    """Apply one transformation in place on the copied record."""
    for segment in segments[:-1]:
        node = node[int(segment)] if isinstance(node, list) else node[segment]
    last = segments[-1]
    if isinstance(node, list):
        # Array elements are never removed (indices must stay stable); both
        # redact and drop blank them out.
        node[int(last)] = None
    elif action == "drop":
        del node[last]
    else:
        node[last] = None


def _deidentify_record(record: dict, rules: list, policy: dict[str, str]) -> tuple[dict, list[dict]]:
    hits = _record_hits(record, rules)
    transformed = copy.deepcopy(record)
    transformations = []
    for segments, (cats, _sources) in hits.items():
        action = min(
            (policy.get(category, "keep") for category in cats),
            key=lambda a: _ACTION_PRIORITY[a],
        )
        if action == "keep":
            continue
        transformations.append(
            {
                "path": _pointer(segments),
                "action": action,
                "categories": [c for c in CATEGORIES if c in cats],
            }
        )
        _apply_action(transformed, segments, action)
    transformations.sort(key=lambda item: item["path"])
    return transformed, transformations


def deidentify_request(payload: Any) -> list[dict]:
    """Validate a /v1/deidentify payload and de-identify every record."""
    records = _validate_records(payload)
    if "policy" not in payload:
        raise InvalidRequest("policy is required")
    rules = _parse_rules(payload.get("schema"))
    policy = _parse_policy(payload["policy"])
    results = []
    for index, record in enumerate(records):
        transformed, transformations = _deidentify_record(record, rules, policy)
        results.append(
            {"index": index, "record": transformed, "transformations": transformations}
        )
    return results

import http.client
import json
import threading
import unittest
from http.server import ThreadingHTTPServer

from privacare import __version__
from privacare.server import Handler


class HttpTestBase(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.httpd = ThreadingHTTPServer(("127.0.0.1", 0), Handler)
        cls.port = cls.httpd.server_address[1]
        cls.thread = threading.Thread(target=cls.httpd.serve_forever, daemon=True)
        cls.thread.start()

    @classmethod
    def tearDownClass(cls):
        cls.httpd.shutdown()
        cls.httpd.server_close()
        cls.thread.join()

    def request(self, method, path, body=None, content_type=None):
        conn = http.client.HTTPConnection("127.0.0.1", self.port, timeout=5)
        headers = {}
        if content_type is not None:
            headers["Content-Type"] = content_type
        conn.request(method, path, body=body, headers=headers)
        resp = conn.getresponse()
        raw = resp.read()
        conn.close()
        return resp.status, json.loads(raw)


class ClassifyHttpTest(HttpTestBase):
    def post(self, payload, content_type="application/json"):
        body = payload if isinstance(payload, (str, bytes)) else json.dumps(payload)
        return self.request("POST", "/v1/classify", body=body, content_type=content_type)

    def test_healthz_unchanged(self):
        status, payload = self.request("GET", "/healthz")
        self.assertEqual(status, 200)
        self.assertEqual(
            payload,
            {"status": "ok", "service": "privacare", "version": __version__},
        )

    def test_unknown_path_404(self):
        status, payload = self.request("GET", "/nope")
        self.assertEqual(status, 404)
        self.assertEqual(payload["error"]["code"], "not_found")

    def test_classify_happy_path(self):
        status, payload = self.post(
            {
                "records": [
                    {"name": "张三", "contact": {"phone": "13800138000"}},
                    {"note": "nothing"},
                ],
                "schema": {"/note": "clinical"},
            }
        )
        self.assertEqual(status, 200)
        results = payload["results"]
        self.assertEqual([r["index"] for r in results], [0, 1])
        fields = {f["path"]: f for f in results[0]["fields"]}
        self.assertEqual(fields["/name"]["categories"], ["direct_identifier"])
        self.assertEqual(fields["/contact/phone"]["categories"], ["contact"])
        self.assertEqual(fields["/contact/phone"]["sources"], ["field_name", "value"])
        self.assertEqual(
            results[1]["fields"],
            [{"categories": ["clinical"], "path": "/note", "sources": ["schema"]}],
        )
        # 原始值不得回显
        self.assertNotIn("张三", json.dumps(payload, ensure_ascii=False))
        self.assertNotIn("13800138000", json.dumps(payload))

    def test_unsupported_media_type(self):
        status, payload = self.post({"records": [{}]}, content_type="text/plain")
        self.assertEqual(status, 415)
        self.assertEqual(payload["error"]["code"], "unsupported_media_type")

    def test_missing_content_type(self):
        status, payload = self.request("POST", "/v1/classify", body="{}")
        self.assertEqual(status, 415)
        self.assertEqual(payload["error"]["code"], "unsupported_media_type")

    def test_invalid_json(self):
        status, payload = self.post("{not json")
        self.assertEqual(status, 400)
        self.assertEqual(payload["error"]["code"], "invalid_json")

    def test_invalid_request(self):
        for body in ("[]", "{}", '{"records": []}', '{"records": [1]}'):
            with self.subTest(body=body):
                status, payload = self.post(body)
                self.assertEqual(status, 422)
                self.assertEqual(payload["error"]["code"], "invalid_request")

    def test_invalid_schema(self):
        status, payload = self.post({"records": [{}], "schema": {"/x": "nope"}})
        self.assertEqual(status, 422)
        self.assertEqual(payload["error"]["code"], "invalid_schema")

    def test_method_not_allowed(self):
        for method in ("GET", "PUT", "DELETE", "PATCH"):
            with self.subTest(method=method):
                status, payload = self.request(method, "/v1/classify")
                self.assertEqual(status, 405)
                self.assertEqual(payload["error"]["code"], "method_not_allowed")

    def test_error_body_has_no_sensitive_values(self):
        secret = "11010519491231002X"
        status, payload = self.post({"records": [{"id": secret}], "schema": "bad"})
        self.assertEqual(status, 422)
        self.assertNotIn(secret, json.dumps(payload))


if __name__ == "__main__":
    unittest.main()

import copy
import http.client
import json
import threading
import unittest
from http.server import ThreadingHTTPServer

from privacare.classifier import InvalidRequest, InvalidSchema
from privacare.deidentifier import InvalidPolicy
from privacare.server import Handler
from privacare.service import Service

VALID_ID = "11010519491231002X"  # checksum-valid mainland ID
VALID_CARD = "4111111111111111"  # Luhn-valid card number


def deidentify(payload):
    return Service().deidentify(payload)


class PolicyActionTest(unittest.TestCase):
    def test_keep_redact_drop(self):
        [result] = deidentify(
            {
                "records": [{"name": "张三", "email": "a@b.com", "age": 45, "note": "plain"}],
                "policy": {
                    "direct_identifier": "drop",
                    "contact": "redact",
                    "quasi_identifier": "keep",
                },
            }
        )
        record = result["record"]
        self.assertNotIn("name", record)
        self.assertIsNone(record["email"])
        self.assertEqual(record["age"], 45)
        self.assertEqual(record["note"], "plain")
        transformations = {t["path"]: t for t in result["transformations"]}
        self.assertEqual(
            transformations["/name"],
            {"path": "/name", "action": "drop", "categories": ["direct_identifier"]},
        )
        self.assertEqual(
            transformations["/email"],
            {"path": "/email", "action": "redact", "categories": ["contact"]},
        )
        self.assertNotIn("/age", transformations)
        self.assertNotIn("/note", transformations)

    def test_unconfigured_categories_default_to_keep(self):
        [result] = deidentify(
            {
                "records": [{"name": "张三", "age": 45}],
                "policy": {"direct_identifier": "redact"},
            }
        )
        self.assertIsNone(result["record"]["name"])
        self.assertEqual(result["record"]["age"], 45)
        self.assertEqual([t["path"] for t in result["transformations"]], ["/name"])

    def test_multi_category_priority_drop_over_redact_over_keep(self):
        record = {"id_card": VALID_ID}  # direct_identifier via name and value
        payload = {
            "records": [record],
            "schema": {"/id_card": ["contact", "clinical"]},
        }
        # contact=redact + clinical=keep + direct=keep -> redact wins over keep
        [result] = deidentify(
            {**payload, "policy": {"contact": "redact", "clinical": "keep"}}
        )
        self.assertIsNone(result["record"]["id_card"])
        [t] = result["transformations"]
        self.assertEqual(t["action"], "redact")
        self.assertEqual(
            t["categories"], ["direct_identifier", "contact", "clinical"]
        )
        # drop anywhere wins overall
        [result] = deidentify(
            {**payload, "policy": {"contact": "redact", "clinical": "drop"}}
        )
        self.assertNotIn("id_card", result["record"])
        [t] = result["transformations"]
        self.assertEqual(t["action"], "drop")

    def test_drop_array_element_becomes_null_and_containers_stay(self):
        [result] = deidentify(
            {
                "records": [
                    {
                        "phones": ["13800138000", "13900139000"],
                        "patient": {"name": "张三"},
                    }
                ],
                "policy": {"contact": "drop", "direct_identifier": "drop"},
            }
        )
        self.assertEqual(result["record"]["phones"], [None, None])
        self.assertEqual(result["record"]["patient"], {})  # empty parent kept

    def test_transformations_sorted_and_value_free(self):
        [result] = deidentify(
            {
                "records": [{"b": "x@y.com", "a": "13800138000", "c": {"id": VALID_ID}}],
                "policy": {"contact": "redact", "direct_identifier": "redact"},
            }
        )
        paths = [t["path"] for t in result["transformations"]]
        self.assertEqual(paths, sorted(paths))
        for t in result["transformations"]:
            self.assertEqual(set(t), {"path", "action", "categories"})
        blob = json.dumps(result, ensure_ascii=False)
        self.assertNotIn("x@y.com", blob)
        self.assertNotIn("13800138000", blob)
        self.assertNotIn(VALID_ID, blob)

    def test_schema_rules_apply(self):
        [result] = deidentify(
            {
                "records": [{"note": "hello", "other": "world"}],
                "schema": {"/note": "clinical"},
                "policy": {"clinical": "redact"},
            }
        )
        self.assertIsNone(result["record"]["note"])
        self.assertEqual(result["record"]["other"], "world")

    def test_results_follow_input_order(self):
        results = deidentify(
            {
                "records": [{"name": "a"}, {"foo": "bar"}, {"email": "a@b.com"}],
                "policy": {"direct_identifier": "drop", "contact": "redact"},
            }
        )
        self.assertEqual([r["index"] for r in results], [0, 1, 2])
        self.assertEqual(results[1]["record"], {"foo": "bar"})
        self.assertEqual(results[1]["transformations"], [])

    def test_caller_data_not_mutated_and_deterministic(self):
        payload = {
            "records": [{"name": "张三", "phones": ["13800138000"]}],
            "policy": {"direct_identifier": "drop", "contact": "drop"},
        }
        snapshot = copy.deepcopy(payload)
        first = deidentify(payload)
        second = deidentify(payload)
        self.assertEqual(payload, snapshot)
        self.assertEqual(first, second)


class PolicyValidationTest(unittest.TestCase):
    def test_invalid_policy(self):
        bad = [
            "redact",
            [],
            {},
            {"unknown": "keep"},
            {"contact": "hide"},
            {"contact": ["redact"]},
            {"contact": None},
            {"contact": "redact", "bogus": "keep"},
        ]
        for policy in bad:
            with self.subTest(policy=policy):
                with self.assertRaises(InvalidPolicy):
                    deidentify({"records": [{}], "policy": policy})

    def test_missing_policy_is_invalid_request(self):
        with self.assertRaises(InvalidRequest):
            deidentify({"records": [{}]})

    def test_invalid_request(self):
        bad = [
            None,
            [],
            "x",
            {},
            {"records": None, "policy": {"contact": "keep"}},
            {"records": [], "policy": {"contact": "keep"}},
            {"records": [1], "policy": {"contact": "keep"}},
        ]
        for payload in bad:
            with self.subTest(payload=payload):
                with self.assertRaises(InvalidRequest):
                    deidentify(payload)

    def test_invalid_schema(self):
        with self.assertRaises(InvalidSchema):
            deidentify(
                {
                    "records": [{}],
                    "schema": {"/x": "nope"},
                    "policy": {"contact": "keep"},
                }
            )


class DeidentifyHttpTest(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.httpd = ThreadingHTTPServer(("127.0.0.1", 0), Handler)
        cls.port = cls.httpd.server_address[1]
        cls.thread = threading.Thread(target=cls.httpd.serve_forever, daemon=True)
        cls.thread.start()

    @classmethod
    def tearDownClass(cls):
        cls.httpd.shutdown()
        cls.httpd.server_close()
        cls.thread.join()

    def request(self, method, path, body=None, content_type=None):
        conn = http.client.HTTPConnection("127.0.0.1", self.port, timeout=5)
        headers = {}
        if content_type is not None:
            headers["Content-Type"] = content_type
        conn.request(method, path, body=body, headers=headers)
        resp = conn.getresponse()
        raw = resp.read()
        allow = resp.getheader("Allow")
        conn.close()
        return resp.status, json.loads(raw), allow

    def post(self, payload, content_type="application/json"):
        body = payload if isinstance(payload, (str, bytes)) else json.dumps(payload)
        return self.request("POST", "/v1/deidentify", body=body, content_type=content_type)

    def test_happy_path(self):
        status, payload, _ = self.post(
            {
                "records": [{"name": "张三", "contact": {"phone": "13800138000"}}],
                "policy": {"direct_identifier": "drop", "contact": "redact"},
            }
        )
        self.assertEqual(status, 200)
        [result] = payload["results"]
        self.assertEqual(result["index"], 0)
        self.assertEqual(result["record"], {"contact": {"phone": None}})
        blob = json.dumps(payload, ensure_ascii=False)
        self.assertNotIn("张三", blob)
        self.assertNotIn("13800138000", blob)

    def test_method_not_allowed(self):
        for method in ("GET", "PUT", "DELETE", "PATCH"):
            with self.subTest(method=method):
                status, payload, allow = self.request(method, "/v1/deidentify")
                self.assertEqual(status, 405)
                self.assertEqual(payload["error"]["code"], "method_not_allowed")
                self.assertEqual(allow, "POST")

    def test_unsupported_media_type(self):
        status, payload, _ = self.post(
            {"records": [{}], "policy": {"contact": "keep"}}, content_type="text/plain"
        )
        self.assertEqual(status, 415)
        self.assertEqual(payload["error"]["code"], "unsupported_media_type")

    def test_invalid_json(self):
        status, payload, _ = self.post("{not json")
        self.assertEqual(status, 400)
        self.assertEqual(payload["error"]["code"], "invalid_json")

    def test_invalid_request(self):
        for body in ("[]", "{}", '{"records": []}', '{"records": [{}]}'):
            with self.subTest(body=body):
                status, payload, _ = self.post(body)
                self.assertEqual(status, 422)
                self.assertEqual(payload["error"]["code"], "invalid_request")

    def test_invalid_schema(self):
        status, payload, _ = self.post(
            {"records": [{}], "schema": "bad", "policy": {"contact": "keep"}}
        )
        self.assertEqual(status, 422)
        self.assertEqual(payload["error"]["code"], "invalid_schema")

    def test_invalid_policy(self):
        for policy in ('"redact"', "[]", "{}", '{"unknown": "keep"}', '{"contact": ["redact"]}'):
            with self.subTest(policy=policy):
                status, payload, _ = self.post(
                    '{"records": [{"id": "secret"}], "policy": %s}' % policy
                )
                self.assertEqual(status, 422)
                self.assertEqual(payload["error"]["code"], "invalid_policy")
                self.assertNotIn("secret", json.dumps(payload))


if __name__ == "__main__":
    unittest.main()

